class Solution {
public:
    int nthSuperUglyNumber(int n, vector<int>& primes) {
        vector<long long> dp(n, 1);
        int k = primes.size();
        vector<int> indices(k, 0);
        for (int i = 1; i < n; ++i) {
            long long nextVal = LLONG_MAX;
            for (int j = 0; j < k; ++j) {
                nextVal = min(nextVal, dp[indices[j]] * primes[j]);
            }
            dp[i] = nextVal;
            for (int j = 0; j < k; ++j) {
                if (dp[indices[j]] * primes[j] == nextVal) {
                    indices[j]++;
                }
            }
        }
        return static_cast<int>(dp[n - 1]);
    }
};

class Solution {
    public int nthSuperUglyNumber(int n, int[] primes) {
        long[] dp = new long[n];
        dp[0] = 1;
        int k = primes.length;
        int[] indices = new int[k];
        for (int i = 1; i < n; i++) {
            long nextVal = Long.MAX_VALUE;
            for (int j = 0; j < k; j++) {
                nextVal = Math.min(nextVal, dp[indices[j]] * primes[j]);
            }
            dp[i] = nextVal;
            for (int j = 0; j < k; j++) {
                if (dp[indices[j]] * primes[j] == nextVal) {
                    indices[j]++;
                }
            }
        }
        return (int) dp[n - 1];
    }
}

