var nthSuperUglyNumber = function(n, primes) {
    const dp = new Array(n).fill(1);
    const k = primes.length;
    const indices = new Array(k).fill(0);
    for (let i = 1; i < n; i++) {
        let nextVal = Infinity;
        for (let j = 0; j < k; j++) {
            const cand = dp[indices[j]] * primes[j];
            if (cand < nextVal) nextVal = cand;
        }
        dp[i] = nextVal;
        for (let j = 0; j < k; j++) {
            if (dp[indices[j]] * primes[j] === nextVal) {
                indices[j]++;
            }
        }
    }
    return dp[n - 1];
};
